<template>
 <div class="personal-usage" :aria-busy="loading">
  <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon />
  <section v-if="data" class="provider-grid" aria-label="供应商账户用量">
   <article class="provider-card deepseek"><header><span class="provider-logo"><img src="/provider-logos/deepseek.ico" alt="DeepSeek 标识"/></span><div><h3>DeepSeek</h3><small>API 账户余额</small></div><span class="status">{{status(data.deepseek)}}</span></header>
    <template v-if="data.deepseek.status==='ok'"><div v-for="balance in data.deepseek.balances" :key="balance.currency" class="balance"><strong>{{balance.currency==='CNY'?'¥':'$'}}{{balance.total}}</strong><span>{{balance.currency}} 可用余额</span><small>充值余额 {{balance.toppedUp??'未知'}} · 赠送余额 {{balance.granted??'未知'}}</small></div><p v-if="!data.deepseek.available" class="notice">平台返回账户当前不可调用，请检查余额或账户状态。</p></template>
    <p v-else class="notice">{{data.deepseek.message}}</p><footer><span>{{updated(data.deepseek.checkedAt)}}</span><a href="https://platform.deepseek.com/usage" target="_blank" rel="noopener noreferrer">平台账单 ↗</a></footer>
   </article>
   <article class="provider-card glm"><header><span class="provider-logo"><img src="/provider-logos/glm.png" alt="智谱 标识"/></span><div><h3>GLM · 智谱</h3><small>API 账户余额</small></div><span class="status">{{status(data.glm)}}</span></header>
    <template v-if="data.glm.status==='ok'"><div class="balance"><strong>¥{{data.glm.balance}}</strong><span>CNY 可用余额</span><small>累计消费 {{data.glm.totalSpent===null?'未提供':'¥'+data.glm.totalSpent}} · 今日消费 {{data.glm.todaySpent===null?'未提供':'¥'+data.glm.todaySpent}}</small></div></template>
    <p v-else class="notice">{{data.glm.message}}</p><footer><span>{{updated(data.glm.checkedAt)}}</span><a href="https://open.bigmodel.cn/" target="_blank" rel="noopener noreferrer">智谱控制台 ↗</a></footer>
   </article>
   <article v-if="data.hunyuan && data.hunyuan.status!=='unconfigured'" class="provider-card hunyuan"><header><span class="provider-logo"><img src="/provider-logos/hunyuan.svg" alt="腾讯混元 标识"/></span><div><h3>腾讯混元</h3><small>{{data.hunyuan.plans?.[0]?.name||'Token Plan 个人版'}}</small></div><span class="status">{{status(data.hunyuan)}}</span></header>
    <template v-if="data.hunyuan.status==='ok'"><div v-for="(plan,index) in data.hunyuan.plans" :key="index" class="plan-usage"><h4 v-if="data.hunyuan.plans.length>1">{{plan.name}}</h4><div class="balance"><strong>{{credits(plan.remaining)}} <small>积分剩余</small></strong><span>已用 {{credits(plan.used)}} / {{credits(plan.capacity)}} 积分</span></div><el-progress v-if="plan.usedPercent!==null" :percentage="clamp(plan.usedPercent)" :show-text="false" :stroke-width="7" color="#427cba" /><small>到期 {{plan.expiresAt?time(plan.expiresAt):'未提供'}}</small></div></template>
    <p v-else class="notice">{{data.hunyuan.message}}</p><footer><span>{{updated(data.hunyuan.checkedAt)}}</span></footer>
   </article>
   <article class="provider-card codex"><header><span class="provider-logo"><img src="/provider-logos/openai.svg" alt="OpenAI 标识"/></span><div><h3>Codex</h3><small>{{data.codex.source||'本机账户用量'}}</small></div><span class="status">{{status(data.codex)}}</span></header>
    <template v-if="['ok','snapshot'].includes(data.codex.status)"><p v-if="data.codex.status==='snapshot'" class="notice">{{snapshotNotice(data.codex.checkedAt)}}</p><div v-for="(window,index) in data.codex.windows" :key="index" class="quota-window"><div><span>{{windowLabel(window)}}</span><strong>{{percent(window.usedPercent)}} 已用</strong></div><el-progress v-if="window.usedPercent!==null" :percentage="clamp(window.usedPercent)" :show-text="false" :stroke-width="7" color="#3d6657" /><small>重置时间 {{window.resetsAt?time(window.resetsAt*1000):'平台未提供'}}</small></div><div class="codex-total"><small>账户累计 Token</small><strong>{{format(data.codex.summary.lifetimeTokens)}}</strong></div><p class="card-help">账户额度与 API 余额独立；累计 Token 为 Codex 平台统计，不是本项目调用量。</p></template>
    <p v-else class="notice">{{data.codex.message}}</p><footer><span>{{updated(data.codex.checkedAt)}}</span></footer>
   </article>
  </section>
  <section class="system-usage">
   <header><div><h3>本系统调用用量</h3><p>仅统计本系统接入记录后的调用。</p></div></header>
   <form class="usage-dates" @submit.prevent="loadSummary"><label>开始日期<input v-model="from" type="date" required aria-label="用量开始日期" /></label><label>结束日期<input v-model="to" type="date" required aria-label="用量结束日期" /></label><el-button native-type="submit" type="primary" :loading="summaryLoading">查询用量</el-button></form>
   <el-alert v-if="summaryError" :title="summaryError" type="error" :closable="false" />
   <div v-if="summaryData" class="system-metrics"><article v-for="provider in ['deepseek','glm']" :key="provider"><h4>{{provider==='deepseek'?'DeepSeek':'GLM'}}</h4><strong>{{format(summaryData.providers?.[provider]?.totalTokens??0)}} <small>Token 已记录</small></strong><p>{{summaryData.providers?.[provider]?.modelCalls??0}} 次模型调用<span v-if="summaryData.providers?.[provider]?.unknownTokenCalls"> · {{summaryData.providers[provider].unknownTokenCalls}} 次未返回用量</span></p></article></div>
   <p class="card-help">每次可查 31 天，未返回的 Token 不计为零。</p>
  </section>
 </div>
</template>
<script setup>
import {ref,onMounted} from 'vue'
import {getPersonalUsage,getPersonalUsageSummary} from '../api'
const data=ref(null),loading=ref(false),error=ref(''),summaryData=ref(null),summaryLoading=ref(false),summaryError=ref('')
const today=new Date(Date.now()+8*3600000).toISOString().slice(0,10),from=ref(today),to=ref(today)
const time=value=>new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})
const snapshotNotice=value=>{const age=Date.now()-Date.parse(value);return !Number.isFinite(age)||age>36*3600000?'快照已过期，请检查本机同步。计划每日09:00采集；电脑需开机。':'每日09:00同步一次（电脑需开机），当前为采集时快照。'}
const updated=value=>value?'采集于 '+time(value):'尚未采集'
const status=value=>({ok:'已连接',snapshot:'同步快照',unconfigured:'未接入',unavailable:'暂不可用',empty:'无套餐'})[value.status]||'未知'
const credits=value=>value!==null&&value!==undefined&&Number.isFinite(Number(value))?Number(value).toLocaleString('zh-CN',{maximumFractionDigits:2}):'未提供'
const format=value=>typeof value==='number'?value.toLocaleString('zh-CN'):'未提供'
const percent=value=>typeof value==='number'?value+'%':'未知'
const clamp=value=>Math.max(0,Math.min(100,value))
const windowLabel=value=>value.windowDurationMins===10080?'每周额度':value.windowDurationMins===300?'5 小时额度':value.windowDurationMins?`${value.windowDurationMins} 分钟额度`:'账户额度'
async function load(){if(loading.value)return;loading.value=true;error.value='';try{data.value=(await getPersonalUsage()).data}catch(e){error.value=e.response?.data?.msg||'用量读取失败'}finally{loading.value=false}}
let sequence=0
async function loadSummary(){const id=++sequence;summaryLoading.value=true;summaryError.value='';try{const result=(await getPersonalUsageSummary({from:from.value,to:to.value})).data;if(id===sequence)summaryData.value=result}catch(e){if(id===sequence){summaryData.value=null;summaryError.value=e.response?.data?.msg||'系统用量读取失败'}}finally{if(id===sequence)summaryLoading.value=false}}
onMounted(()=>{load();loadSummary()})
</script>
<style scoped>
.personal-usage{display:grid;gap:22px;color:#263d50}.system-usage>header{display:flex;justify-content:space-between;align-items:center;gap:16px}h2,h3,h4,p{margin:0}.system-usage>header p{font-size:13px;line-height:1.8;color:#7b8997;margin-top:8px}.provider-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;align-items:stretch}.provider-card{display:flex;flex-direction:column;background:white;border:1px solid #dfe7ee;border-radius:14px;padding:24px;min-width:0}.provider-card>header{display:flex;gap:12px;align-items:center;margin-bottom:30px}.provider-logo{display:grid;place-items:center;width:42px;height:42px;background:#edf3ff;color:#4261c6;border-radius:12px;font-weight:800;font-size:22px;flex:none}.provider-logo img{width:30px;height:30px;object-fit:contain}.codex .provider-logo{background:#f4f4f4!important}.glm .provider-logo{background:#f0edfc;color:#785eb5}.hunyuan .provider-logo{background:#edf4fc;color:#427cba}.plan-usage{display:grid;gap:14px}.plan-usage+ .plan-usage{margin-top:24px}.plan-usage>small{font-size:11px;color:#8a98a7}.plan-usage .balance>strong>small{font-size:12px;font-weight:400;color:#7c8e9f}.codex .provider-logo{background:#ebf5ee;color:#386c51}.provider-card h3{font-size:18px;margin-bottom:5px}.provider-card header small,.status{font-size:11px;color:#8895a4}.status{margin-left:auto;white-space:nowrap}.balance{display:grid;gap:10px}.balance>strong{font-size:38px;font-weight:650;color:#233f60}.balance span{font-size:13px;color:#7c8e9f}.balance small,.quota-window small{font-size:11px;line-height:1.8;color:#8a98a7}.provider-card>footer{display:flex;justify-content:space-between;gap:8px;align-items:flex-end;margin-top:auto;padding-top:28px;color:#97a2af;font-size:10px;flex-wrap:wrap}.provider-card a{font-size:12px;text-decoration:none;color:#087f83}.notice{font-size:13px;line-height:1.9;color:#8b754b;background:#fcf8ef;border-radius:7px;padding:14px;margin-bottom:16px}.quota-window{margin-bottom:22px}.quota-window>div:first-child{display:flex;justify-content:space-between;gap:10px;font-size:12px;margin-bottom:12px}.quota-window strong{font-size:13px}.quota-window small{display:block;margin-top:10px}.codex-total{display:grid;gap:8px}.codex-total small{font-size:11px;color:#8a98a7}.codex-total strong{font-size:23px;overflow-wrap:anywhere}.card-help{color:#8a98a7;font-size:11px;line-height:1.8;margin-top:18px}.system-usage{background:white;border:1px solid #dfe7ee;border-radius:14px;padding:24px}.system-usage h3{font-size:18px}.usage-dates{display:flex;gap:14px;align-items:flex-end;flex-wrap:wrap;margin:24px 0}.usage-dates label{display:grid;gap:8px;font-size:12px;color:#7c8b9c}.usage-dates input{padding:8px 12px;height:36px;box-sizing:border-box;border:1px solid #dce3eb;border-radius:6px;font:inherit;color:#43596b;background:white;min-width:0}.system-metrics{display:grid;grid-template-columns:1fr 1fr;gap:16px}.system-metrics article{border:1px solid #e6edf1;border-radius:10px;padding:20px;background:#f8fafc}.system-metrics h4{font-size:13px;font-weight:500;color:#657a8e;margin-bottom:14px}.system-metrics strong{font-size:24px;font-weight:650}.system-metrics strong small{font-size:11px;font-weight:400;color:#91a0ae}.system-metrics p{font-size:12px;color:#8494a4;margin-top:10px;line-height:1.8}@media(max-width:700px){.provider-grid,.system-metrics{grid-template-columns:1fr}.codex{grid-column:auto}.provider-card,.system-usage{padding:20px}.provider-card>header{margin-bottom:24px}.usage-dates label{flex:1;min-width:120px}.usage-dates input,.usage-dates>.el-button{min-height:44px}.usage-dates>.el-button{width:100%}}
</style>
